import { Component } from '@angular/core';

@Component({
  selector: 'app-ejercicio19',
  templateUrl: './ejercicio19.component.html',
  styleUrls: ['./ejercicio19.component.css']
})
export class Ejercicio19Component {
  productName: string = '';
  selectedProductName: string | null = null;

  sendProductName() {
    this.selectedProductName = this.productName;
  }
}
<input type="text" [(ngModel)]="productName" placeholder="Introduce el nombre del producto">
  <button (click)="sendProductName()">Buscar cantidad total</button>

  <!-- El componente hijo se incluye aquí y se le pasa el nombre del producto seleccionado -->
  <app-componente-hijo [productName]="selectedProductName"></app-componente-hijo>
